 35→export const loader = async ({ request }: LoaderFunctionArgs) => {
 36→  const { session, admin } = await authenticate.admin(request);
 37→  const shop = session.shop;
 38→
 39→  let config = await db.widgetConfig.findUnique({ where: { shop } });
 40→
 41→  if (!config) {
