262→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
263→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
264→  if (!rawCss) return "";
265→  const css = rawCss.replace(/<\/style>/gi, "");
266→  let result = "";
267→  let remaining = css;
268→  while (remaining.length > 0) {
269→    const openBrace = remaining.indexOf("{");
270→    if (openBrace === -1) break;
271→    const closeBrace = remaining.indexOf("}", openBrace);
272→    if (closeBrace === -1) break;
273→    const selector = remaining.substring(0, openBrace).trim();
274→    const body = remaining.substring(openBrace + 1, closeBrace);
275→    remaining = remaining.substring(closeBrace + 1);
276→    if (selector.startsWith("@")) {
277→      result += selector + "{" + body + "}";
278→    } else if (selector) {
279→      const prefixed = selector.split(",").map(s => {
280→        s = s.trim();
281→        return s ? "#" + wid + " " + s : "";
282→      }).filter(Boolean).join(", ");
283→      result += prefixed + " {" + body + "}";
284→    }
285→  }
286→  return result;
287→}
